// Any INotionCommand can join the batch — AddBlockCommand,
// UpdateBlockContentCommand, MoveBlockCommand, DeleteBlockCommand…
var batch = new BatchCommand("Insert table row", [
    new AddBlockCommand(blockProvider, blocks, pageId, rowTemplate, afterBlockId),
    new UpdateBlockContentCommand(blockProvider, blocks, tableBlockId, before, after),
]);

// PushAsync executes the batch and records it as one undo step
await commandStack.PushAsync(batch);

// a single Ctrl+Z reverts both commands, last-to-first
await commandStack.UndoAsync();

var batch = new BatchCommand("Clear selection");

foreach (var block in selectedBlocks)
{
    // commands must NOT have been executed yet
    batch.Add(new DeleteBlockCommand(blockProvider, blocks, block));
}

if (batch.Count > 0)
{
    await commandStack.PushAsync(batch);
}

