[JSInvokable]
public async Task OnMarkdownShortcut(string shortcutKey)
{
    var type = MarkdownShortcutDetector.FromJsShortcutKey(shortcutKey);
    if (type is null) return;

    var isChecked = MarkdownShortcutDetector.IsCheckedTodo(shortcutKey);
    await ConvertCurrentBlockAsync(type.Value, isChecked);
}

